function(container, apiUrl, tables) {
  const startDateInput = container.querySelector('input[name="startDate"]');
  const endDateInput = container.querySelector('input[name="endDate"]');
  const budgetInput = container.querySelector('input[name="budget"]');
  const ingredientCategorySelect = container.querySelector('select[name="ingredientCategory"]');
  const mealStyleSelect = container.querySelector('select[name="mealStyle"]');
  const difficultyRadios = container.querySelectorAll('input[name="difficulty"]');
  const excludePreviousCheckbox = container.querySelector('input[name="excludePrevious"]');
  const generateButton = container.querySelector('[data-testid="generate-button"]');
  const familyMembersList = container.querySelector('#family-members-list');
  const constraintsSummary = container.querySelector('#constraints-summary');
  const progressContainer = container.querySelector('#progress-container');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const resultsContainer = container.querySelector('#results-container');
  const initialMessage = container.querySelector('#initial-message');
  const menuResultsTbody = container.querySelector('#menu-results-tbody');
  const viewDetailsButton = container.querySelector('[data-testid="view-details-button"]');
  const saveMenuButton = container.querySelector('[data-testid="save-menu-button"]');

  let currentMenuId = null;
  let familyMembers = [];
  let allergies = [];
  let restrictions = [];

  // 初期化：今日と7日後をデフォルト設定
  const today = new Date();
  const sevenDaysLater = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  startDateInput.value = today.toISOString().split('T')[0];
  endDateInput.value = sevenDaysLater.toISOString().split('T')[0];
  budgetInput.value = '3000';

  // 家族成員データ取得
  async function loadFamilyMembers() {
    const members = await window.aivicApi.list(1); // tableIndex 1 = 家族成員
    if (members) {
      familyMembers = members.filter(m => m.は有効 === true);
      renderFamilyMembers();
    }
  }

  // 家族成員チェックボックス描画
  function renderFamilyMembers() {
    familyMembersList.innerHTML = '';
    familyMembers.forEach(member => {
      const label = document.createElement('label');
      label.style.cssText = 'display: flex; align-items: center; gap: 6px; font-size: 12px; cursor: pointer;';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = member.ユーザーID;
      checkbox.checked = true;
      checkbox.style.accentColor = 'var(--primary)';
      checkbox.dataset.memberId = member.家族成員ID;
      const span = document.createElement('span');
      span.textContent = `${member.成員名}（${member.続柄}）`;
      label.appendChild(checkbox);
      label.appendChild(span);
      familyMembersList.appendChild(label);
    });
  }

  // アレルギー・食事制限情報取得
  async function loadConstraints() {
    allergies = await window.aivicApi.list(2); // tableIndex 2 = アレルギー情報
    restrictions = await window.aivicApi.list(3); // tableIndex 3 = 食事制限情報
    renderConstraintsSummary();
  }

  // 制約条件サマリー描画
  function renderConstraintsSummary() {
    let html = '';

    if (allergies && allergies.length > 0) {
      const activeAllergies = allergies.filter(a => a.有効フラグ === true);
      if (activeAllergies.length > 0) {
        html += '<strong style="color: var(--primary);">🚫 アレルギー:</strong><br/>';
        activeAllergies.slice(0, 3).forEach(a => {
          html += `• ${a.アレルゲン名}（${a.重症度 || '未指定'}）<br/>`;
        });
        if (activeAllergies.length > 3) {
          html += `• 他 ${activeAllergies.length - 3} 件<br/>`;
        }
        html += '<br/>';
      }
    }

    if (restrictions && restrictions.length > 0) {
      const activeRestrictions = restrictions.filter(r => r.有効フラグ === true);
      if (activeRestrictions.length > 0) {
        html += '<strong style="color: var(--primary);">⚠️ 食事制限:</strong><br/>';
        activeRestrictions.slice(0, 3).forEach(r => {
          html += `• ${r.制限種別}: ${r.制限内容}<br/>`;
        });
        if (activeRestrictions.length > 3) {
          html += `• 他 ${activeRestrictions.length - 3} 件<br/>`;
        }
      }
    }

    if (!html) {
      html = '<span style="color: var(--text-muted);">制約条件なし</span>';
    }

    constraintsSummary.innerHTML = html;
  }

  // 献立生成処理
  generateButton.addEventListener('click', async () => {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const budget = parseInt(budgetInput.value) || 3000;
    const ingredientCategory = ingredientCategorySelect.value;
    const mealStyle = mealStyleSelect.value;
    const difficulty = Array.from(difficultyRadios).find(r => r.checked).value;
    const excludePrevious = excludePreviousCheckbox.checked;

    const selectedMembers = Array.from(container.querySelectorAll('input[type="checkbox"][data-member-id]'))
      .filter(cb => cb.checked)
      .map(cb => cb.dataset.memberId);

    if (!startDate || !endDate || selectedMembers.length === 0) {
      alert('開始日、終了日、対象家族成員を選択してください');
      return;
    }

    // UI 更新：プログレス表示
    initialMessage.style.display = 'none';
    resultsContainer.style.display = 'none';
    progressContainer.style.display = 'block';
    progressBar.style.width = '0%';
    progressText.textContent = '0%';
    generateButton.disabled = true;

    // シミュレーション：プログレスアニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + '%';
      progressText.textContent = Math.floor(progress) + '%';
    }, 300);

    // 献立生成ログ保存
    const logData = {
      ユーザーID: 'current-user-id', // 実際にはセッションから取得
      生成リクエスト日: new Date().toISOString(),
      生成対象日: startDate,
      生成期間日数: Math.ceil((new Date(endDate) - new Date(startDate)) / (1000 * 60 * 60 * 24)),
      生成ステータス: '進行中',
      生成条件_予算上限: budget,
      生成条件_食材カテゴリ: ingredientCategory,
    };

    const logSaved = await window.aivicApi.save(11, logData); // tableIndex 11 = 献立生成ログ

    // 献立データ生成（シミュレーション）
    const menuData = {
      ユーザーID: 'current-user-id',
      献立名: `${startDate} ～ ${endDate} の献立`,
      説明: `予算: ${budget}円/日、難易度: ${difficulty}、スタイル: ${mealStyle}`,
      開始日: startDate,
      終了日: endDate,
      ステータス: '下書き',
      作成日時: new Date().toISOString(),
      作成者ID: 'current-user-id',
    };

    const menuSaved = await window.aivicApi.save(5, menuData); // tableIndex 5 = 献立
    if (menuSaved) {
      currentMenuId = menuSaved.id || menuSaved.献立ID;
    }

    // 献立詳細データ生成（サンプル）
    const sampleDishes = [
      { 料理名: '鮭の塩焼き', 食事区分: '朝食', カロリー: 280, タンパク質グラム: 25, 炭水化物グラム: 5, 脂質グラム: 15 },
      { 料理名: 'ご飯', 食事区分: '朝食', カロリー: 150, タンパク質グラム: 3, 炭水化物グラム: 35, 脂質グラム: 0 },
      { 料理名: 'みそ汁', 食事区分: '朝食', カロリー: 50, タンパク質グラム: 3, 炭水化物グラム: 5, 脂質グラム: 1 },
      { 料理名: 'チキンカレー', 食事区分: '昼食', カロリー: 450, タンパク質グラム: 30, 炭水化物グラム: 50, 脂質グラム: 12 },
      { 料理名: 'サラダ', 食事区分: '昼食', カロリー: 100, タンパク質グラム: 5, 炭水化物グラム: 10, 脂質グラム: 4 },
      { 料理名: '豚の生姜焼き', 食事区分: '夕食', カロリー: 380, タンパク質グラム: 28, 炭水化物グラム: 15, 脂質グラム: 18 },
      { 料理名: 'ご飯', 食事区分: '夕食', カロリー: 150, タンパク質グラム: 3, 炭水化物グラム: 35, 脂質グラム: 0 },
      { 料理名: 'スープ', 食事区分: '夕食', カロリー: 80, タンパク質グラム: 4, 炭水化物グラム: 8, 脂質グラム: 2 },
    ];

    for (let i = 0; i < sampleDishes.length; i++) {
      const dish = sampleDishes[i];
      await window.aivicApi.save(6, {
        献立ID: currentMenuId,
        料理名: dish.料理名,
        説明: `${dish.料理名}の説明`,
        食事区分: dish.食事区分,
        順序: i + 1,
        カロリー: dish.カロリー,
        タンパク質グラム: dish.タンパク質グラム,
        炭水化物グラム: dish.炭水化物グラム,
        脂質グラム: dish.脂質グラム,
      }); // tableIndex 6 = 献立詳細
    }

    // プログレス完了
    clearInterval(progressInterval);
    progressBar.style.width = '100%';
    progressText.textContent = '100%';

    // 結果表示
    setTimeout(() => {
      progressContainer.style.display = 'none';
      renderResults(sampleDishes);
      resultsContainer.style.display = 'block';
      generateButton.disabled = false;
    }, 800);
  });

  // 献立結果描画
  function renderResults(dishes) {
    menuResultsTbody.innerHTML = '';
    const dateStart = new Date(startDateInput.value);

    dishes.forEach((dish, index) => {
      const tr = document.createElement('tr');
      tr.style.cssText = 'border-bottom: 1px solid var(--border);';
      tr.innerHTML = `
        <td style="padding: 8px; color: var(--text); font-size: 12px;">${dateStart.toLocaleDateString('ja-JP')}</td>
        <td style="padding: 8px; color: var(--text); font-size: 12px;">${dish.食事区分}</td>
        <td style="padding: 8px; color: var(--text); font-size: 12px; font-weight: 500;">${dish.料理名}</td>
        <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px;">${dish.カロリー} kcal</td>
        <td style="padding: 8px; text-align: center;">
          <button class="view-dish-btn" data-index="${index}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 12px; text-decoration: underline;">詳細</button>
        </td>
      `;
      menuResultsTbody.appendChild(tr);
    });
  }

  // 献立詳細ボタン
  viewDetailsButton.addEventListener('click', () => {
    if (currentMenuId) {
      window.showScreen('scr-1783678257996'); // 献立詳細・確認画面
    }
  });

  // 献立保存ボタン
  saveMenuButton.addEventListener('click', async () => {
    if (currentMenuId) {
      const updated = await window.aivicApi.update(5, currentMenuId, { ステータス: '確定' });
      if (updated) {
        alert('献立を保存しました');
        window.showScreen('scr-1783678243827'); // 献立一覧・生成画面
      }
    }
  });

  // 初期化実行
  loadFamilyMembers();
  loadConstraints();
}

function(container, apiUrl, tables) {
  const familyMemberSelect = container.querySelector('#family-member-select');
  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabPanes = container.querySelectorAll('.tab-pane');
  const saveBtn = container.querySelector('#save-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const errorDiv = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');

  // 現在選択中の家族成員ID
  let currentMemberId = null;

  // 条件データをメモリに保持（家族成員ごと）
  const conditionData = {};

  // タブ切り替え
  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabName = btn.dataset.tab;

      // タブボタンのスタイル更新
      tabButtons.forEach(b => {
        b.style.color = b.dataset.tab === tabName ? 'var(--primary)' : 'var(--text-muted)';
        b.style.borderBottomColor = b.dataset.tab === tabName ? 'var(--primary)' : 'transparent';
      });

      // タブペイン表示/非表示
      tabPanes.forEach(pane => {
        pane.style.display = pane.dataset.tab === tabName ? 'block' : 'none';
      });
    });
  });

  // 初期タブ表示
  if (tabButtons.length > 0) {
    tabButtons[0].click();
  }

  // 家族成員選択時
  familyMemberSelect.addEventListener('change', () => {
    const memberId = familyMemberSelect.value;
    if (!memberId) {
      errorDiv.style.display = 'block';
      errorText.textContent = '家族成員を選択してください';
      return;
    }
    errorDiv.style.display = 'none';

    // 現在のデータを保存
    if (currentMemberId) {
      saveCurrentMemberData();
    }

    currentMemberId = memberId;

    // 新しい成員のデータをロード
    loadMemberData(memberId);
  });

  // 現在の成員のデータを保存
  function saveCurrentMemberData() {
    if (!currentMemberId) return;

    const allergies = Array.from(container.querySelectorAll('.allergy-checkbox:checked')).map(el => el.value);
    const otherAllergies = container.querySelector('#other-allergies').value;
    const religious = Array.from(container.querySelectorAll('.religious-checkbox:checked')).map(el => el.value);
    const medical = Array.from(container.querySelectorAll('.medical-checkbox:checked')).map(el => el.value);
    const otherRestrictions = container.querySelector('#other-restrictions').value;
    const calorieLimit = container.querySelector('#calorie-limit').value;
    const sodiumLimit = container.querySelector('#sodium-limit').value;
    const sugarLimit = container.querySelector('#sugar-limit').value;
    const proteinTarget = container.querySelector('#protein-target').value;
    const fiberTarget = container.querySelector('#fiber-target').value;
    const dislikedFoods = container.querySelector('#disliked-foods').value;
    const likedFoods = container.querySelector('#liked-foods').value;
    const budgetLimit = container.querySelector('#budget-limit').value;

    conditionData[currentMemberId] = {
      allergies,
      otherAllergies,
      religious,
      medical,
      otherRestrictions,
      calorieLimit,
      sodiumLimit,
      sugarLimit,
      proteinTarget,
      fiberTarget,
      dislikedFoods,
      likedFoods,
      budgetLimit
    };
  }

  // 成員のデータをロード
  function loadMemberData(memberId) {
    const data = conditionData[memberId] || {};

    // アレルギー
    container.querySelectorAll('.allergy-checkbox').forEach(el => {
      el.checked = (data.allergies || []).includes(el.value);
    });
    container.querySelector('#other-allergies').value = data.otherAllergies || '';

    // 食事制限
    container.querySelectorAll('.religious-checkbox').forEach(el => {
      el.checked = (data.religious || []).includes(el.value);
    });
    container.querySelectorAll('.medical-checkbox').forEach(el => {
      el.checked = (data.medical || []).includes(el.value);
    });
    container.querySelector('#other-restrictions').value = data.otherRestrictions || '';

    // 栄養目標
    container.querySelector('#calorie-limit').value = data.calorieLimit || '';
    container.querySelector('#sodium-limit').value = data.sodiumLimit || '';
    container.querySelector('#sugar-limit').value = data.sugarLimit || '';
    container.querySelector('#protein-target').value = data.proteinTarget || '';
    container.querySelector('#fiber-target').value = data.fiberTarget || '';

    // 好み・予算
    container.querySelector('#disliked-foods').value = data.dislikedFoods || '';
    container.querySelector('#liked-foods').value = data.likedFoods || '';
    container.querySelector('#budget-limit').value = data.budgetLimit || '';
  }

  // 保存ボタン
  saveBtn.addEventListener('click', async () => {
    if (!currentMemberId) {
      errorDiv.style.display = 'block';
      errorText.textContent = '家族成員を選択してください';
      return;
    }

    // 現在のデータを保存
    saveCurrentMemberData();

    // すべての成員の条件を DB に保存
    try {
      saveBtn.disabled = true;
      saveBtn.textContent = '保存中...';

      // 食事制限情報テーブルに保存（tableIndex は仕様から推定）
      // 実際には複数の成員データを一括保存する処理が必要
      for (const memberId in conditionData) {
        const data = conditionData[memberId];

        // アレルギー情報を保存
        if (data.allergies && data.allergies.length > 0) {
          for (const allergen of data.allergies) {
            await window.aivicApi.save(2, {
              allergenName: allergen,
              severity: '中度',
              description: '',
              activeFlag: true
            });
          }
        }

        // 食事制限情報を保存
        const restrictions = [...data.religious, ...data.medical];
        if (restrictions.length > 0) {
          for (const restriction of restrictions) {
            await window.aivicApi.save(3, {
              restrictionType: restriction,
              restrictionContent: `${restriction}制限`,
              priority: 5,
              activeFlag: true
            });
          }
        }
      }

      errorDiv.style.display = 'none';

      // 献立生成画面へ遷移
      setTimeout(() => {
        window.showScreen('scr-1783678328203');
      }, 500);
    } catch (err) {
      errorDiv.style.display = 'block';
      errorText.textContent = '保存に失敗しました。もう一度お試しください。';
      saveBtn.disabled = false;
      saveBtn.textContent = '保存して献立生成へ';
    }
  });

  // キャンセルボタン
  cancelBtn.addEventListener('click', () => {
    window.showScreen('scr-1783678243827');
  });

  // 初期状態
  errorDiv.style.display = 'block';
  errorText.textContent = '家族成員を選択してください';
}

function(container, apiUrl, tables) {
  const familyMemberSelect = container.querySelector('[data-testid="family-member-select"]');
  const startDateInput = container.querySelector('[data-testid="start-date"]');
  const endDateInput = container.querySelector('[data-testid="end-date"]');
  const allergyCheckboxes = container.querySelectorAll('[data-testid^="allergy-"]');
  const restrictionCheckboxes = container.querySelectorAll('[data-testid^="restriction-"]');
  const saveConditionCheckbox = container.querySelector('[data-testid="save-condition"]');
  const generateButton = container.querySelector('[data-testid="generate-button"]');
  const cancelButton = container.querySelector('[data-testid="cancel-button"]');
  const loadPreviousBtn = container.querySelector('[data-testid="load-previous-btn"]');
  const viewHistoryBtn = container.querySelector('[data-testid="view-history-btn"]');
  const confirmOverlay = container.querySelector('#confirm-overlay');
  const confirmCancelBtn = container.querySelector('[data-testid="confirm-cancel-btn"]');
  const confirmExecuteBtn = container.querySelector('[data-testid="confirm-execute-btn"]');
  const progressSection = container.querySelector('#progress-section');
  const progressBar = container.querySelector('#progress-bar');
  const progressPercent = container.querySelector('#progress-percent');

  // 初期日付設定（今日から7日間）
  const today = new Date();
  const endDate = new Date(today);
  endDate.setDate(endDate.getDate() + 6);
  startDateInput.value = today.toISOString().split('T')[0];
  endDateInput.value = endDate.toISOString().split('T')[0];

  // プレビュー更新関数
  function updatePreview() {
    const member = familyMemberSelect.value || '全員';
    const memberLabel = familyMemberSelect.options[familyMemberSelect.selectedIndex]?.text || '全員';
    const period = startDateInput.value && endDateInput.value 
      ? `${startDateInput.value} ～ ${endDateInput.value}`
      : '未設定';
    const allergies = Array.from(allergyCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => cb.nextElementSibling?.textContent || cb.value)
      .join('、') || 'なし';
    const restrictions = Array.from(restrictionCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => cb.nextElementSibling?.textContent || cb.value)
      .join('、') || 'なし';

    container.querySelector('#preview-member').textContent = memberLabel;
    container.querySelector('#preview-period').textContent = period;
    container.querySelector('#preview-allergies').textContent = allergies;
    container.querySelector('#preview-restrictions').textContent = restrictions;
  }

  // イベントリスナー
  familyMemberSelect.addEventListener('change', updatePreview);
  startDateInput.addEventListener('change', updatePreview);
  endDateInput.addEventListener('change', updatePreview);
  allergyCheckboxes.forEach(cb => cb.addEventListener('change', updatePreview));
  restrictionCheckboxes.forEach(cb => cb.addEventListener('change', updatePreview));

  // 前回条件を読み込む
  loadPreviousBtn.addEventListener('click', () => {
    startDateInput.value = '2024-01-08';
    endDateInput.value = '2024-01-14';
    familyMemberSelect.value = 'member-1';

    // アレルギー・制限をチェック
    container.querySelector('[data-testid="allergy-egg"]').checked = true;
    container.querySelector('[data-testid="allergy-milk"]').checked = true;
    container.querySelector('[data-testid="restriction-low-salt"]').checked = true;

    updatePreview();
  });

  // 食事評価履歴を確認
  viewHistoryBtn.addEventListener('click', () => {
    window.showScreen('scr-1783678300297');
  });

  // 献立生成実行
  generateButton.addEventListener('click', () => {
    if (!startDateInput.value || !endDateInput.value) {
      alert('開始日と終了日を指定してください');
      return;
    }

    // 確認ダイアログを表示
    const summary = container.querySelector('#confirm-summary');
    const member = familyMemberSelect.options[familyMemberSelect.selectedIndex]?.text || '全員';
    const allergies = Array.from(allergyCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => cb.nextElementSibling?.textContent || cb.value)
      .join('、') || 'なし';
    const restrictions = Array.from(restrictionCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => cb.nextElementSibling?.textContent || cb.value)
      .join('、') || 'なし';

    summary.innerHTML = `
      <div><strong>対象:</strong> ${member}</div>
      <div><strong>期間:</strong> ${startDateInput.value} ～ ${endDateInput.value}</div>
      <div><strong>アレルギー:</strong> ${allergies}</div>
      <div><strong>制限:</strong> ${restrictions}</div>
      ${saveConditionCheckbox.checked ? '<div><strong>条件を保存:</strong> はい</div>' : ''}
    `;
    confirmOverlay.style.display = 'flex';
  });

  // 確認ダイアログ：キャンセル
  confirmCancelBtn.addEventListener('click', () => {
    confirmOverlay.style.display = 'none';
  });

  // 確認ダイアログ：実行
  confirmExecuteBtn.addEventListener('click', async () => {
    confirmOverlay.style.display = 'none';
    progressSection.style.display = 'block';

    // 献立生成ログを保存
    const logData = {
      userId: 'current-user-id',
      familyMemberId: familyMemberSelect.value || null,
      generationRequestDate: new Date().toISOString(),
      generationTargetDate: startDateInput.value,
      generationPeriodDays: Math.ceil((new Date(endDateInput.value) - new Date(startDateInput.value)) / (1000 * 60 * 60 * 24)) + 1,
      generationStatus: '進行中',
