  const table = container.querySelector('[data-testid="shopping-list-table"]');

  let currentShoppingList = [];

  // 初期日付設定（今日から7日間）
  const today = new Date();
  const sevenDaysLater = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  startDateInput.valueAsDate = today;
  endDateInput.valueAsDate = sevenDaysLater;

  // 期間プリセット処理
  const periodRadios = container.querySelectorAll('input[name="periodPreset"]');
  periodRadios.forEach(radio => {
