  // 全員チェックボックク処理
  const allMemberCheckbox = container.querySelector('input[value="all"]');
  const memberCheckboxes = Array.from(container.querySelectorAll('input[name="familyMember"]')).filter(cb => cb.value !== 'all');

  allMemberCheckbox.addEventListener('change', (e) => {
    memberCheckboxes.forEach(cb => {
      cb.checked = e.target.checked;
    });
  });

  memberCheckboxes.forEach(cb => {
    cb.addEventListener('change', () => {
      const allChecked = memberCheckboxes.every(c => c.checked);
      allMemberCheckbox.checked = allChecked;
