    statusDiv.style.display = 'block';
    statusMessage.textContent = '買い物リストを生成中...';
    generateButton.disabled = true;

    try {
      // 選択条件を収集
      const selectedAllergens = Array.from(container.querySelectorAll('input[name="allergen"]:checked')).map(cb => cb.value);
      const selectedRestrictions = Array.from(container.querySelectorAll('input[name="restriction"]:checked')).map(cb => cb.value);
      const selectedMembers = Array.from(container.querySelectorAll('input[name="familyMember"]:checked')).map(cb => cb.value);

      // ダミーデータ生成（実際のAPI呼び出しの代わり）
      const mockShoppingList = [
        { id: '1', name: '鶏むね肉', quantity: 600, unit: 'g', category: '肉類' },
        { id: '2', name: '豚肉（薄切り）', quantity: 400, unit: 'g', category: '肉類' },
        { id: '3', name: '卵', quantity: 12, unit: '個', category: '卵・�乳製品' },
        { id: '4', name: '牛乳', quantity: 1000, unit: 'ml', category: '卵・乳製品' },
        { id: '5', name: 'トマト', quantity: 4, unit: '個', category: '野菜' },
        { id: '6', name: 'キャベツ', quantity: 1, unit: '玉', category: '野菜' },
        { id: '7', name: 'ニンジン', quantity: 3, unit: '本', category: '野菜' },
        { id: '8', name: '玉ねぎ', quantity: 5, unit: '個', category: '野菜' },
        { id: '9', name: '米', quantity: 5, unit: 'kg', category: '穀類' },
        { id: '10', name: '小麦粉', quantity: 500, unit: 'g', category: '穀類' },
        { id: '11', name: 'バター', quantity: 200, unit: 'g', category: '卵・乳製品' },
        { id: '12', name: 'チーズ', quantity: 300, unit: 'g', category: '卵・乳製品' },
      ];

      // アレルギー・制限に基づいてフィルタリング
      let filteredList = mockShoppingList;

      if (selectedAllergens.includes('egg')) {
        filteredList = filteredList.filter(item => item.name !== '卵');
      }
      if (selectedAllergens.includes('milk')) {
        filteredList = filteredList.filter(item => !['牛乳', 'バター', 'チーズ'].includes(item.name));
      }
      if (selectedAllergens.includes('wheat')) {
        filteredList = filteredList.filter(item => item.name !== '小麦粉');
      }

      currentShoppingList = filteredList;

      // テーブル更新
      renderShoppingList();

      statusMessage.textContent = `✓ 買い物リストを生成しました（${filteredList.length}件）`;
      setTimeout(() => {
        statusDiv.style.display = 'none';
      }, 3000);

    } catch (error) {
      statusMessage.textContent = `✗ エラーが発生しました: ${error.message}`;
      console.error('Generation error:', error);
    } finally {
      generateButton.disabled = false;
    }
  });

  // テーブル描画
  function renderShoppingList() {
    tbody.innerHTML = '';
    listCountSpan.textContent = `${currentShoppingList.length}件`;

    if (currentShoppingList.length === 0) {
      tbody.innerHTML = `
        <tr style="background: var(--bg-card);">
          <td colspan="4" style="padding: 24px; text-align: center; color: var(--text-muted); font-size: 12px;">
            リストを生成してください
          </td>
        </tr>
      `;
      return;
    }

    currentShoppingList.forEach((item, index) => {
      const row = document.createElement('tr');
      row.style.background = index % 2 === 0 ? 'var(--bg-card)' : 'var(--bg-main)';
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 8px; color: var(--text);">${item.name}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${item.quantity}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${item.unit}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${item.category}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // CSVエクスポート
  exportButton.addEventListener('click', () => {
    if (currentShoppingList.length === 0) {
      alert('エクスポートするリストがありません');
      return;
    }

    const headers = ['食材名', '数量', '単位', 'カテゴリ'];
    const rows = currentShoppingList.map(item => [
      item.name,
      item.quantity,
      item.unit,
      item.category
    ]);

    const csv = [
      '\uFEFF' + headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `shopping-list-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 初期表示
  renderShoppingList();
}

function(container, apiUrl, tables) {
  const menuIdParam = new URLSearchParams(window.location.search).get('menuId');
  const actionTypeRadios = container.querySelectorAll('input[name="action-type"]');
  const reasonCategoriesSection = container.querySelector('#reason-categories-section');
  const detailSection = container.querySelector('#detail-section');
  const modificationSection = container.querySelector('#modification-section');
  const detailTextarea = container.querySelector('#detail-textarea');
  const modificationTextarea = container.querySelector('#modification-textarea');
  const cancelButton = container.querySelector('#cancel-button');
  const submitButton = container.querySelector('#submit-button');
  const menuPreview = container.querySelector('#menu-preview');
  const menuDishes = container.querySelector('#menu-dishes');

  let currentMenu = null;

  // 献立データを取得して表示
  async function loadMenuData() {
    if (!menuIdParam) {
      menuPreview.innerHTML = '<div style="color: var(--text-muted); font-size: 12px;">献立情報が見つかりません</div>';
      return;
    }

    const menus = await window.aivicApi.list(0); // 献立テーブル
    if (!menus) return;

    currentMenu = menus.find(m => m.id === menuIdParam);
    if (!currentMenu) {
      menuPreview.innerHTML = '<div style="color: var(--text-muted); font-size: 12px;">献立が見つかりません</div>';
      return;
    }

    // 献立情報を表示
    const startDate = currentMenu.開始日 ? new Date(currentMenu.開始日).toLocaleDateString('ja-JP') : '-';
    const endDate = currentMenu.終了日 ? new Date(currentMenu.終了日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#preview-menu-name').textContent = currentMenu.献立名 || '-';
    container.querySelector('#preview-menu-period').textContent = `${startDate} ～ ${endDate}`;
    container.querySelector('#preview-menu-family').textContent = currentMenu.対象家族成員ID ? '指定家族成員' : '全員対象';

    // 献立詳細を取得して表示
    const details = await window.aivicApi.list(1); // 献立詳細テーブル
    if (details) {
      const menuDetails = details.filter(d => d.献立ID === menuIdParam);
      const dishesHtml = menuDetails
        .sort((a, b) => (a.順序 || 0) - (b.順序 || 0))
        .map(d => {
          const mealType = d.食事区分 || '不明';
          const dishName = d.料理名 || '無名料理';
          const cal = d.カロリー ? `${d.カロリー}kcal` : '';
          return `<div style="padding: 6px 0; border-bottom: 1px solid var(--border);">
            <div style="font-weight: 500; color: var(--text);">${mealType}: ${dishName}</div>
            ${cal ? `<div style="font-size: 11px; color: var(--text-muted);">${cal}</div>` : ''}
          </div>`;
        })
        .join('');
      menuDishes.innerHTML = dishesHtml || '<div style="color: var(--text-muted);">献立詳細がありません</div>';
    }
  }

  // 対応方法選択時の処理
  actionTypeRadios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      const actionType = e.target.value;
      reasonCategoriesSection.style.display = 'block';
      detailSection.style.display = 'block';
      modificationSection.style.display = actionType === 'modify' ? 'block' : 'none';
    });
  });

  // キャンセルボタン
  cancelButton.addEventListener('click', () => {
    window.showScreen('scr-1783678257996'); // 献立詳細・確認画面へ
  });

  // 送信ボタン
  submitButton.addEventListener('click', async () => {
    const actionType = container.querySelector('input[name="action-type"]:checked')?.value;
    if (!actionType) {
      alert('対応方法を選択してください');
      return;
    }

