      .map(cb => cb.value);
    const detail = detailTextarea.value.trim();
    const modification = modificationTextarea.value.trim();

    if (!detail && !modification) {
      alert('詳細説明を入力してください');
      return;
    }

    // 食事評価レコードを作成（フィードバック記録）
    const feedbackRecord = {
      ユーザーID: window.currentUserId || 'unknown',
      献立ID: menuIdParam,
      評価日: new Date().toISOString(),
      総合評価: actionType === 'reject' ? 1 : 3,
      コメント: `[${actionType === 'reject' ? '却下' : '修正'}] カテゴリ: ${reasonCategories.join(', ') || 'なし'}\n詳細: ${detail}\n${modification ? `修正内容: ${modification}` : ''}`,
      再度提案希望: actionType === 'modify',
    };

    const saved = await window.aivicApi.save(2, feedbackRecord); // 食事評価テーブル
    if (saved) {
      alert(`フィードバックを送信しました`);
      window.showScreen('scr-1783678257996'); // 献立詳細・確認画面へ
    }
  });

  // 初期化
  loadMenuData();
}
